const localObjectUrls=new Map();
async function hydrateMedia(){const targets=[...document.querySelectorAll('img[data-local-media]')];for(const img of targets){const id=img.dataset.localMedia;if(!id||localObjectUrls.has(id)){if(localObjectUrls.has(id))img.src=localObjectUrls.get(id);continue}let d;try{d=await db();const blob=await new Promise((resolve,reject)=>{const req=d.transaction('media','readonly').objectStore('media').get(id);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});if(blob){const url=URL.createObjectURL(blob);localObjectUrls.set(id,url);img.src=url}}catch{}finally{d?.close()}}
}
const mediaObserver=new MutationObserver(()=>{if(route()==='resultados'){document.querySelectorAll('.card-image').forEach(button=>{const v=state.listings.find(x=>x.id===button.dataset.id),id=v?.photoSlots?.find(s=>s?.mediaId&&!s.mediaId.startsWith('sample-'))?.mediaId,img=button.querySelector('img');if(id&&img)img.dataset.localMedia=id})}if(route()==='anuncio'||route()==='mis-anuncios'){const id=location.hash.split('/')[1],v=state.listings.find(x=>x.id===id),hero=$('.detail-hero');if(v&&hero&&!$('.gallery-strip')){const photos=vehicleGallery(v),strip=document.createElement('div');strip.className='gallery-strip';photos.forEach((photo,i)=>{const button=document.createElement('button');button.type='button';button.className=`gallery-thumb${i===0?' active':''}`;button.dataset.action='gallery-photo';if(photo.mediaId)button.dataset.galleryMedia=photo.mediaId;if(photo.src)button.dataset.gallerySrc=photo.src;button.setAttribute('aria-label',`Ver foto ${i+1} de ${v.title}`);const img=document.createElement('img');if(photo.mediaId)img.dataset.localMedia=photo.mediaId;if(photo.src)img.src=photo.src;img.alt=`Foto ${i+1} de ${v.title}`;button.append(img);strip.append(button)});if(photos[0]?.mediaId)hero.dataset.localMedia=photos[0].mediaId;hero.after(strip)}}if(route()==='publicar'&&Number(new URLSearchParams(location.hash.split('?')[1]||'').get('step'))===2){const v=state.drafts[profile()?.id];document.querySelectorAll('.photo-slot').forEach(label=>{if(label.querySelector('.photo-preview'))return;const i=Number(label.querySelector('[data-photo-index]')?.dataset.photoIndex),slot=v?.photoSlots?.[i];if(!slot?.mediaId)return;const img=document.createElement('img');img.className='photo-preview';img.dataset.localMedia=slot.mediaId;img.alt=`Vista previa ${i+1}`;label.prepend(img)})}hydrateMedia()});
mediaObserver.observe($('#app-view'),{childList:true,subtree:true});document.addEventListener('click',e=>{const button=e.target.closest('[data-action="gallery-photo"]');if(!button)return;const src=button.dataset.gallerySrc||(button.dataset.galleryMedia&&localObjectUrls.get(button.dataset.galleryMedia));if(!src)return;const hero=$('.detail-hero');if(hero)hero.src=src;document.querySelectorAll('.gallery-thumb').forEach(item=>item.classList.toggle('active',item===button))});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action="doc-open"]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();const listing=state.listings.find(v=>v.id===b.dataset.id),doc=listing?.documents?.find(d=>d.name===b.dataset.doc);if(!doc?.mediaId)return;try{const d=await db(),blob=await new Promise((resolve,reject)=>{const req=d.transaction('media','readonly').objectStore('media').get(doc.mediaId);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});if(!blob){d.close();toast('Archivo local no disponible.');return}d.close();const url=URL.createObjectURL(blob);const view=blob.type==='application/pdf'?`<iframe class="document-preview" src="${esc(url)}" title="${esc(doc.filename||doc.name)}"></iframe>`:`<img class="document-image-preview" src="${esc(url)}" alt="${esc(doc.filename||doc.name)}">`;openModal(`<div class="modal-form"><button type="button" class="modal-x" data-action="close-modal" aria-label="Cerrar">×</button><p class="eyebrow">Evidencia privada · ${esc(doc.name)}</p><h2>${esc(doc.filename||'Archivo adjunto')}</h2>${view}<a class="button button-light full" href="${esc(url)}" download="${esc(doc.filename||'documento')}">Descargar en este navegador</a></div>`)}catch{toast('No se pudo abrir el archivo guardado en este navegador.')}},true);
document.addEventListener('click',e=>{if($('#wizard-form')&&(e.target.closest('[data-route]')||e.target.closest('a[href^="#"]')))saveWizard()},true);
function formValues(form){return Object.fromEntries(new FormData(form).entries())}
function readWizard(){const f=$('#wizard-form');if(!f)return null;const old=state.drafts[profile().id]||{};const fd=new FormData(f);const obj={...old,...Object.fromEntries(fd.entries())};obj.id=fd.get('id');obj.ownerId=profile().id;obj.kind=fd.get('kind')||old.kind||'Carro';obj.price=Number(fd.get('price'))||old.price||0;obj.year=Number(fd.get('year'))||old.year||0;obj.km=Number(fd.get('km'))||old.km||0;obj.authorization=fd.get('authorization')==='on';obj.verified=!!profile().verified;obj.documents=old.documents||DOCS.map(name=>({name,status:'missing'}));obj.photoSlots=old.photoSlots||[];obj.photos=obj.photoSlots.filter(x=>x?.mediaId).length;obj.image=old.image||imgs[0];obj.public=false;return obj}
function saveWizard(){const v=readWizard();if(!v)return;state.drafts[profile().id]=v;const existing=state.listings.findIndex(x=>x.id===v.id);if(existing>=0){state.listings[existing]={...state.listings[existing],...v,status:state.listings[existing].status==='needs_fix'?'needs_fix':'draft'};}save()}
function db(){return new Promise((resolve,reject)=>{const req=indexedDB.open(DB_NAME,1);req.onupgradeneeded=()=>req.result.createObjectStore('media');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function mediaPut(id,file){let d;try{d=await db();await new Promise((resolve,reject)=>{const tx=d.transaction('media','readwrite');tx.objectStore('media').put(file,id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});return true}catch{toast('No se pudo guardar el archivo local. Revisa el almacenamiento del navegador.');return false}finally{d?.close()}}
function updateWizardAndRender(step){saveWizard();go(`publicar?step=${step}`)}
function openModal(html){const m=$('#modal');m.innerHTML=html;m.showModal()}
function contact(id,visit=false){const v=state.listings.find(x=>x.id===id);if(!v)return;openModal(`<form id="${visit?'visit':'lead'}-form" data-id="${esc(id)}" class="modal-form"><button type="button" class="modal-x" data-action="close-modal" aria-label="Cerrar">×</button><p class="eyebrow">${visit?'Solicitar una visita':'Contacto al vendedor'}</p><h2>${visit?'Coordina para conocer':'Pregunta por'} ${esc(v.title)}</h2><p class="muted">Esta demo simula el contacto: no abre WhatsApp ni envía información. La solicitud quedará en el espacio del vendedor.</p><label class="form-field">Tu nombre<input name="name" required></label><label class="form-field">Celular o correo<input name="contact" required></label>${visit?`<div class="form-grid"><label class="form-field">Día preferido<input name="day" type="date" required></label><label class="form-field">Hora preferida<select name="time"><option>10:00 a. m.</option><option>12:00 p. m.</option><option>3:00 p. m.</option><option>5:00 p. m.</option></select></label></div>`:`<label class="form-field">Mensaje<textarea name="message" rows="3">Hola, quiero conocer disponibilidad y más detalles.</textarea></label>`}<label class="check-consent"><input type="checkbox" name="consent" required><span>Autorizo que este vendedor me contacte sobre esta solicitud.</span></label><button class="button button-primary full">${visit?'Solicitar visita':'Enviar solicitud'}</button></form>`)}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action="approve"]');if(!b)return;const v=state.listings.find(x=>x.id===b.dataset.id);if(!v)return;const pending=checklist(v).filter(x=>!x.done);const docs=(v.documents||[]).filter(d=>!['reviewed','verified'].includes(d.status));if(pending.length||docs.length){e.preventDefault();e.stopImmediatePropagation();toast('No se puede aprobar: revisa requisitos y marca los documentos como revisados o verificados.')}},true);
document.addEventListener('click',async e=>{const routeBtn=e.target.closest('[data-route]');if(routeBtn){e.preventDefault();go(routeBtn.dataset.route);return}const b=e.target.closest('[data-action]');if(!b)return;const {action,id}=b.dataset;
if(action==='filters-open'){syncFilterDraft();$('#filters-modal').showModal();return}if(action==='close-filters'){$('#filters-modal').close();return}if(action==='apply-filters'){applyFilterDraft();return}if(action==='detail'){go(`anuncio/${id}`);return}if(action==='private-detail'){go(`mis-anuncios/${id}`);return}if(action==='favorite'){state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];save();render();return}if(action==='clear-filters'){const modal=$('#filters-modal');if(modal.contains(b)){resetFilterDraft();return}appliedFilters={city:'all',seller:'all',min:'',max:'',year:0};state.sort='relevance';save();catalogPage=1;render();return}if(action==='page'){catalogPage=Math.max(1,Number(b.dataset.page)||1);render();$('#app-view').scrollIntoView({block:'start'});return}if(action==='contact'||action==='visit'){contact(id,action==='visit');return}if(action==='close-modal'){$('#modal').close();return}if(action==='logout'){state.session=null;save();toast('Sesión demo cerrada.');go('resultados');return}if(action==='toggle-listing'){const v=state.listings.find(x=>x.id===id);if(v){v.status=v.status==='paused'?'published':'paused';v.public=v.status==='published';save();render();toast(`Anuncio ${statusLabel(v.status).toLowerCase()}.`)}return}if(action==='step'){if($('#wizard-form'))saveWizard();go(`publicar?step=${b.dataset.step}`);return}if(action==='prev-step'||action==='next-step'){saveWizard();const step=Number($('#wizard-form').dataset.step)+(action==='next-step'?1:-1);go(`publicar?step=${Math.max(0,Math.min(5,step))}`);return}if(action==='edit-listing'){go(`publicar?edit=${id}&step=0`);return}if(action==='submit-listing'){saveWizard();const v=state.drafts[profile().id];const checks=checklist(v);const duplicate=!!v.vin&&state.listings.some(x=>x.id!==v.id&&x.vin&&x.vin===v.vin);v.duplicateWarning=duplicate;if(checks.some(c=>!c.done)){toast('Completa los requisitos pendientes antes de enviar.');render();return}v.status='in_review';v.public=false;v.createdAt=Date.now();if(!state.listings.some(x=>x.id===v.id))state.listings.push(v);delete state.drafts[profile().id];save();toast(duplicate?'Anuncio enviado a revisión manual por posible duplicado.':'Anuncio enviado a revisión.');go('panel');return}
if(action==='demo-login'){ensureProfiles();const role=b.dataset.role;let p=state.profiles.find(x=>x.role===role);if(!p){p={id:uid(role),name:'Operador Vitrina',role,email:`${role}@demo.co`,verified:true};state.profiles.push(p)}state.session=p.id;save();go(role==='moderator'?'moderacion':'panel');return}
if(action==='approve'||action==='request-fix'||action==='remove'){const v=state.listings.find(x=>x.id===id);if(!v)return;let reason='';if(action!=='approve'){reason=prompt(action==='remove'?'Motivo de retiro (se mostrará al vendedor):':'Indica qué debe corregir el vendedor:','Completa la información o adjuntos pendientes.');if(!reason)return}if(action==='approve'){v.status='published';v.public=true;v.verified=true;v.documents=(v.documents||[]).map(d=>d.status==='uploaded'?{...d,status:'reviewed'}:d);v.moderationReason='';}else if(action==='request-fix'){v.status='needs_fix';v.public=false;v.moderationReason=reason;v.appealable=true;}else{v.status='removed';v.public=false;v.moderationReason=reason;}state.moderation.push({id:uid('decision'),listingId:id,action,reason,at:Date.now()});save();render();toast(action==='approve'?'Anuncio aprobado y visible en el catálogo.':'Cambio guardado; el vendedor verá el motivo.');return}
if(action==='doc-review'||action==='doc-verify'||action==='doc-expire'){const v=state.listings.find(x=>x.id===id);const d=v?.documents?.find(x=>x.name===b.dataset.doc);if(d)d.status=action==='doc-review'?'reviewed':action==='doc-verify'?'verified':'expired';save();render();return}
if(action==='appeal'){const v=state.listings.find(x=>x.id===id);if(v&&!(v.appeals||0)){v.appeals=1;v.status='in_review';v.public=false;save();render();toast('Apelación registrada para revisión.')}return}
});
document.addEventListener('input',e=>{if(e.target.closest('#wizard-form')){const f=$('#wizard-form');if(f&&['text','number','textarea'].includes(e.target.type)||e.target.tagName==='TEXTAREA'){clearTimeout(window.autosaveTimer);window.autosaveTimer=setTimeout(saveWizard,350)}}if(e.target.id==='search-input'){catalogPage=1;render()}});
document.addEventListener('change',e=>{if(e.target.id==='dealer-org'){state.dealerOrg=e.target.value;save();render()}if(e.target.id==='dealer-branch'){state.dealerBranch=e.target.value;save();render()}if(e.target.id==='register-role'){const dealer=e.target.value==='dealer';['legalName','nit','representative','branch'].forEach(name=>{const input=$(`[name="${name}"]`);if(input)input.required=dealer})}});
document.addEventListener('change',async e=>{if(e.target.id==='register-role'){$('#dealer-fields').hidden=e.target.value!=='dealer';return}if(['filter-city','filter-seller','filter-year','sort-filter'].includes(e.target.id)){return}if(e.target.closest('#wizard-form')){const f=$('#wizard-form');if(e.target.name==='kind'){saveWizard();go(`publicar?step=1`);return}if(e.target.dataset.photoIndex!==undefined&&e.target.files?.[0]){const i=Number(e.target.dataset.photoIndex),v=readWizard();const mediaId=uid('photo');if(await mediaPut(mediaId,e.target.files[0])){v.photoSlots[i]={mediaId,uploaded:true};v.photos=v.photoSlots.filter(x=>x?.mediaId).length;v.image=imgs[0];state.drafts[profile().id]=v;save();render()}return}if(e.target.dataset.document&&e.target.files?.[0]){const v=readWizard(),name=e.target.dataset.document,mediaId=uid('doc');if(await mediaPut(mediaId,e.target.files[0])){v.documents=(v.documents||[]).filter(d=>d.name!==name);v.documents.push({name,status:'uploaded',mediaId,filename:e.target.files[0].name});state.drafts[profile().id]=v;save();render()}return}saveWizard()}});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target;if(f.id==='search-form'){render();return}if(f.id==='register-form'){const d=formValues(f);if(d.code!=='123456'){toast('Código incorrecto. Para la demo usa 123456.');return}if(state.profiles.some(p=>p.email.toLowerCase()===d.email.toLowerCase())){toast('Ese correo ya tiene perfil. Ingresa desde aquí.');return}const p={id:uid('user'),name:d.name,documentType:d.documentType,documentNumber:d.documentNumber,email:d.email,phone:d.phone,city:d.city,role:d.role,verified:true,consents:{account:true,contact:d.contactConsent==='on',marketing:d.marketingConsent==='on'}};if(d.role==='dealer')Object.assign(p,{legalName:d.legalName,nit:d.nit,representative:d.representative,branch:d.branch,branches:[d.branch]});state.profiles.push(p);state.session=p.id;save();toast('Cuenta demo creada e identidad validada.');go(d.role==='buyer'?'resultados':'panel');return}if(f.id==='login-form'){const d=formValues(f),p=state.profiles.find(x=>x.email.toLowerCase()===d.email.toLowerCase());if(d.code!=='123456'||!p){toast('Correo o código incorrecto. Usa el código demo 123456.');return}state.session=p.id;save();go(p.role==='moderator'?'moderacion':'panel');return}if(f.id==='lead-form'||f.id==='visit-form'){const d=formValues(f),v=state.listings.find(x=>x.id===f.dataset.id);if(!v)return;if(f.id==='lead-form')state.leads.push({id:uid('lead'),listingId:v.id,ownerId:v.ownerId,name:d.name,contact:d.contact,message:d.message,channel:'Solicitud web',status:'Nuevo',at:Date.now()});else state.visits.push({id:uid('visit'),listingId:v.id,ownerId:v.ownerId,name:d.name,contact:d.contact,day:d.day,time:d.time,vehicle:v.title,status:'Solicitada'});save();$('#modal').close();toast(f.id==='lead-form'?'Solicitud asociada al vendedor.':'Visita solicitada; falta confirmación del vendedor.');return}});
window.addEventListener('hashchange',render);
$('#reset-demo').addEventListener('click',()=>{if(!confirm('¿Reiniciar perfiles, anuncios, contactos y borradores de esta demo?'))return;localStorage.removeItem(STORE);state=initial();state.listings=seedListings.map(v=>({...v}));indexedDB.deleteDatabase(DB_NAME);render();go('resultados');toast('Demo reiniciada.')});
ensureProfiles();render();
